-- ============================================================
-- 悬赏平台 数据库 Schema v0.2 — PostgreSQL 15/16
-- 约定：
--   1. 主键统一 BIGINT / INTEGER + GENERATED BY DEFAULT AS IDENTITY
--   2. 金额统一 NUMERIC(12,2)，禁止 FLOAT/DOUBLE
--   3. 状态字段用 SMALLINT + 行尾注释枚举，不用 ENUM 类型
--   4. 软删除统一 deleted SMALLINT（0 正常 / 1 删除）
--   5. 所有时间 TIMESTAMP（无时区），updated_at 由触发器维护
--   6. 不加物理外键，一致性由应用层保证
--   7. 索引名 / 唯一约束名在 PostgreSQL 里是「全库唯一」的（MySQL 是每表唯一），
--      所以统一加了表前缀：idx_task_* / idx_order_* / uk_pay_* ...
--
-- 执行：psql -h localhost -p 5432 -U bounty -d bounty -f schema.sql
-- ============================================================

-- 与 JDBC / JDK 默认时区对齐，保证 LOCALTIMESTAMP 与 Java 侧一致
ALTER DATABASE bounty SET timezone TO 'Asia/Shanghai';

SET client_encoding = 'UTF8';
SET client_min_messages = warning;

-- ------------------------------------------------------------
-- updated_at 自动维护（替代 MySQL 的 ON UPDATE CURRENT_TIMESTAMP）
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := LOCALTIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ============================================================
-- 1. 用户
-- ============================================================
DROP TABLE IF EXISTS t_user;
CREATE TABLE t_user (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  phone             VARCHAR(20)  NOT NULL,                 -- 手机号（登录账号）
  nickname          VARCHAR(64)  NOT NULL DEFAULT '',      -- 昵称
  avatar            VARCHAR(255) NOT NULL DEFAULT '',      -- 头像 URL
  gender            SMALLINT     NOT NULL DEFAULT 0,       -- 0未知 1男 2女
  status            SMALLINT     NOT NULL DEFAULT 1,       -- 1正常 0封禁 2注销中
  credit_score      INTEGER      NOT NULL DEFAULT 1000,    -- 信誉分 0-10000
  realname_status   SMALLINT     NOT NULL DEFAULT 0,       -- 0未认证 1审核中 2已认证 3认证失败
  is_publisher      SMALLINT     NOT NULL DEFAULT 0,       -- 1 曾发布过任务
  member_level      SMALLINT     NOT NULL DEFAULT 0,       -- 0普通 1年卡
  member_expire_at  TIMESTAMP    NULL,                     -- 会员到期时间
  invite_code       VARCHAR(16)  NULL,                     -- 我的邀请码（注册时生成）
  inviter_id        BIGINT       NOT NULL DEFAULT 0,       -- 邀请人 ID
  register_ip       VARCHAR(64)  NOT NULL DEFAULT '',      -- 注册 IP
  device_id         VARCHAR(64)  NOT NULL DEFAULT '',      -- 注册设备指纹
  last_login_at     TIMESTAMP    NULL,
  created_at        TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at        TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  deleted           SMALLINT     NOT NULL DEFAULT 0,
  CONSTRAINT uk_user_phone       UNIQUE (phone),
  CONSTRAINT uk_user_invite_code UNIQUE (invite_code)
);
CREATE INDEX idx_user_inviter ON t_user (inviter_id);
CREATE INDEX idx_user_device  ON t_user (device_id);
CREATE INDEX idx_user_created ON t_user (created_at);
COMMENT ON TABLE t_user IS '用户';
CREATE TRIGGER trg_user_updated_at BEFORE UPDATE ON t_user
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 2. 实名认证
-- ============================================================
DROP TABLE IF EXISTS t_user_realname;
CREATE TABLE t_user_realname (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id         BIGINT       NOT NULL,
  real_name       VARCHAR(128) NOT NULL,                   -- 姓名（AES-GCM 密文）
  id_card_cipher  VARCHAR(255) NOT NULL,                   -- 身份证号（AES-GCM 密文）
  id_card_hash    CHAR(64)     NOT NULL,                   -- 身份证 SHA256，用于唯一性校验
  id_card_mask    VARCHAR(24)  NOT NULL DEFAULT '',        -- 脱敏展示 如 3301**********1234
  phone           VARCHAR(20)  NOT NULL DEFAULT '',
  status          SMALLINT     NOT NULL DEFAULT 1,         -- 1审核中 2通过 3驳回
  channel         SMALLINT     NOT NULL DEFAULT 1,         -- 1三要素核验 2人工 3人脸
  reject_reason   VARCHAR(255) NOT NULL DEFAULT '',
  verified_at     TIMESTAMP    NULL,
  created_at      TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at      TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_realname_user   UNIQUE (user_id),
  CONSTRAINT uk_realname_idcard UNIQUE (id_card_hash)
);
COMMENT ON TABLE t_user_realname IS '实名认证';

-- ============================================================
-- 3. 钱包（一人一行，只做记账，不存真钱）
-- ============================================================
DROP TABLE IF EXISTS t_wallet;
CREATE TABLE t_wallet (
  user_id        BIGINT       NOT NULL PRIMARY KEY,
  available      NUMERIC(12,2) NOT NULL DEFAULT 0.00,      -- 可用余额
  frozen         NUMERIC(12,2) NOT NULL DEFAULT 0.00,      -- 冻结（提现中）
  pending        NUMERIC(12,2) NOT NULL DEFAULT 0.00,      -- 待结算（任务审核中）
  total_income   NUMERIC(12,2) NOT NULL DEFAULT 0.00,      -- 累计收入
  total_withdraw NUMERIC(12,2) NOT NULL DEFAULT 0.00,      -- 累计提现
  version        INTEGER       NOT NULL DEFAULT 0,         -- 乐观锁
  updated_at     TIMESTAMP     NOT NULL DEFAULT LOCALTIMESTAMP
);
COMMENT ON TABLE t_wallet IS '用户钱包';
CREATE TRIGGER trg_wallet_updated_at BEFORE UPDATE ON t_wallet
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 4. 资金流水（唯一可信账本，余额只能由它推导）
-- ============================================================
DROP TABLE IF EXISTS t_wallet_flow;
CREATE TABLE t_wallet_flow (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id        BIGINT       NOT NULL,
  biz_no         VARCHAR(64)  NOT NULL,                    -- 业务幂等号，唯一
  biz_type       VARCHAR(32)  NOT NULL,                    -- TASK_INCOME/INVITE_REWARD/WITHDRAW/WITHDRAW_REFUND/MEMBER/PROMOTION/ADJUST
  biz_id         BIGINT       NOT NULL DEFAULT 0,          -- 关联业务主键
  direction      SMALLINT     NOT NULL,                    -- 1 收入 -1 支出
  amount         NUMERIC(12,2) NOT NULL,
  balance_after  NUMERIC(12,2) NOT NULL,                   -- 变动后可用余额快照
  remark         VARCHAR(255) NOT NULL DEFAULT '',
  created_at     TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_flow_biz_no UNIQUE (biz_no)
);
CREATE INDEX idx_flow_user_time ON t_wallet_flow (user_id, created_at);
CREATE INDEX idx_flow_type_time ON t_wallet_flow (biz_type, created_at);
COMMENT ON TABLE t_wallet_flow IS '资金流水';

-- ============================================================
-- 5. 任务分类
-- ============================================================
DROP TABLE IF EXISTS t_task_category;
CREATE TABLE t_task_category (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       VARCHAR(32)  NOT NULL,
  icon       VARCHAR(255) NOT NULL DEFAULT '',
  sort       INTEGER      NOT NULL DEFAULT 0,
  status     SMALLINT     NOT NULL DEFAULT 1,
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
COMMENT ON TABLE t_task_category IS '任务分类';

-- ============================================================
-- 6. 任务
-- ============================================================
DROP TABLE IF EXISTS t_task;
CREATE TABLE t_task (
  id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  publisher_id       BIGINT       NOT NULL,                -- 悬赏主 user_id
  category_id        INTEGER      NOT NULL DEFAULT 0,
  title              VARCHAR(128) NOT NULL,
  cover              VARCHAR(255) NOT NULL DEFAULT '',
  intro              VARCHAR(512) NOT NULL DEFAULT '',     -- 一句话简介
  steps              JSONB        NULL,                    -- [{"step":1,"desc":"..."}]
  rules              TEXT         NULL,                    -- 任务要求/注意事项
  unit_price         NUMERIC(10,2) NOT NULL,               -- 单个赏金
  service_fee_rate   NUMERIC(6,4)  NOT NULL DEFAULT 0.1000,-- 平台服务费率
  total_quota        INTEGER      NOT NULL,                -- 总名额
  taken_quota        INTEGER      NOT NULL DEFAULT 0,      -- 已报名数
  finished_quota     INTEGER      NOT NULL DEFAULT 0,      -- 已完成数
  remain_quota       INTEGER      NOT NULL DEFAULT 0,      -- 剩余名额（Redis 为准，此处为快照）
  limit_per_user     SMALLINT     NOT NULL DEFAULT 1,      -- 每人限做次数
  age_limit          SMALLINT     NOT NULL DEFAULT 18,     -- 最低年龄，0 不限
  deadline_minutes   INTEGER      NOT NULL DEFAULT 1440,   -- 报名后完成时限（分钟）
  audit_status       SMALLINT     NOT NULL DEFAULT 0,      -- 0待审 1通过 2驳回
  audit_remark       VARCHAR(255) NOT NULL DEFAULT '',
  status             SMALLINT     NOT NULL DEFAULT 0,      -- 0草稿 1待上架 2展示中 3已暂停 4已结束 5审核失败
  fast_review        SMALLINT     NOT NULL DEFAULT 0,      -- 1 极速快审
  top_until          TIMESTAMP    NULL,                    -- 置顶到期时间
  weight             INTEGER      NOT NULL DEFAULT 0,      -- 排序权重（置顶/快审/人工干预）
  view_count         INTEGER      NOT NULL DEFAULT 0,
  start_at           TIMESTAMP    NULL,                    -- 任务开始时间
  end_at             TIMESTAMP    NULL,                    -- 任务截止时间
  created_at         TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at         TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  deleted            SMALLINT     NOT NULL DEFAULT 0
);
CREATE INDEX idx_task_hall      ON t_task (status, deleted, weight DESC, created_at DESC);
CREATE INDEX idx_task_publisher ON t_task (publisher_id, status);
CREATE INDEX idx_task_category  ON t_task (category_id, status);
CREATE INDEX idx_task_audit     ON t_task (audit_status, created_at);
COMMENT ON TABLE t_task IS '悬赏任务';
CREATE TRIGGER trg_task_updated_at BEFORE UPDATE ON t_task
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 7. 报名单（核心业务表）
-- ============================================================
DROP TABLE IF EXISTS t_task_order;
CREATE TABLE t_task_order (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_no      VARCHAR(32)  NOT NULL,                     -- 业务单号
  task_id       BIGINT       NOT NULL,
  user_id       BIGINT       NOT NULL,
  publisher_id  BIGINT       NOT NULL,
  amount        NUMERIC(10,2) NOT NULL,                    -- 成交赏金
  status        SMALLINT     NOT NULL DEFAULT 0,           -- 0待接单 1进行中 2待审核 3已通过 4已驳回 5已超时 6已结算 7已取消
  apply_at      TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  deadline_at   TIMESTAMP    NOT NULL,                     -- 完成截止时间
  submit_at     TIMESTAMP    NULL,
  review_at     TIMESTAMP    NULL,
  review_remark VARCHAR(255) NOT NULL DEFAULT '',
  settle_at     TIMESTAMP    NULL,
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_order_order_no  UNIQUE (order_no),
  CONSTRAINT uk_order_task_user UNIQUE (task_id, user_id)
);
CREATE INDEX idx_order_user_status ON t_task_order (user_id, status, created_at);
CREATE INDEX idx_order_task_status ON t_task_order (task_id, status);
CREATE INDEX idx_order_deadline    ON t_task_order (status, deadline_at);
CREATE INDEX idx_order_settle      ON t_task_order (status, settle_at);
COMMENT ON TABLE t_task_order IS '任务报名单';
CREATE TRIGGER trg_task_order_updated_at BEFORE UPDATE ON t_task_order
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 8. 提交凭证
-- ============================================================
DROP TABLE IF EXISTS t_task_submission;
CREATE TABLE t_task_submission (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id   BIGINT        NOT NULL,
  user_id    BIGINT        NOT NULL,
  images     JSONB         NOT NULL,                       -- ["https://oss/...jpg"]
  content    VARCHAR(1000) NOT NULL DEFAULT '',            -- 文字说明
  created_at TIMESTAMP     NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_submission_order ON t_task_submission (order_id);
CREATE INDEX idx_submission_user  ON t_task_submission (user_id, created_at);
COMMENT ON TABLE t_task_submission IS '任务提交凭证';

-- ============================================================
-- 9. 审核日志
-- ============================================================
DROP TABLE IF EXISTS t_task_review_log;
CREATE TABLE t_task_review_log (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_id      BIGINT       NOT NULL,
  reviewer_type SMALLINT     NOT NULL,                     -- 1系统 2平台人工 3悬赏主
  reviewer_id   BIGINT       NOT NULL DEFAULT 0,
  result        SMALLINT     NOT NULL,                     -- 1通过 2驳回
  reason        VARCHAR(255) NOT NULL DEFAULT '',
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_review_log_order ON t_task_review_log (order_id);
COMMENT ON TABLE t_task_review_log IS '审核日志';

-- ============================================================
-- 10. 提现单
-- ============================================================
DROP TABLE IF EXISTS t_withdraw;
CREATE TABLE t_withdraw (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  withdraw_no   VARCHAR(32)  NOT NULL,
  user_id       BIGINT       NOT NULL,
  amount        NUMERIC(12,2) NOT NULL,                    -- 申请金额
  fee           NUMERIC(12,2) NOT NULL DEFAULT 0.00,       -- 手续费
  actual_amount NUMERIC(12,2) NOT NULL,                    -- 实际到账
  channel       SMALLINT     NOT NULL DEFAULT 1,           -- 1支付宝 2微信 3银行卡
  account       VARCHAR(128) NOT NULL,                     -- 收款账号
  account_name  VARCHAR(64)  NOT NULL,                     -- 收款姓名
  status        SMALLINT     NOT NULL DEFAULT 0,           -- 0待审核 1审核通过 2打款中 3成功 4失败 5驳回
  third_no      VARCHAR(64)  NOT NULL DEFAULT '',          -- 支付宝转账单号
  fail_reason   VARCHAR(255) NOT NULL DEFAULT '',
  audit_by      BIGINT       NOT NULL DEFAULT 0,
  audit_at      TIMESTAMP    NULL,
  paid_at       TIMESTAMP    NULL,
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_withdraw_no UNIQUE (withdraw_no)
);
CREATE INDEX idx_withdraw_user   ON t_withdraw (user_id, created_at);
CREATE INDEX idx_withdraw_status ON t_withdraw (status, created_at);
COMMENT ON TABLE t_withdraw IS '提现单';
CREATE TRIGGER trg_withdraw_updated_at BEFORE UPDATE ON t_withdraw
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 11. 支付订单（充值 / 会员 / 增值服务）
-- ============================================================
DROP TABLE IF EXISTS t_pay_order;
CREATE TABLE t_pay_order (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_no   VARCHAR(32)  NOT NULL,
  user_id    BIGINT       NOT NULL,
  biz_type   SMALLINT     NOT NULL,                        -- 1任务充值 2会员 3增值服务
  biz_id     BIGINT       NOT NULL DEFAULT 0,
  amount     NUMERIC(12,2) NOT NULL,
  channel    SMALLINT     NOT NULL DEFAULT 1,              -- 1支付宝 2微信
  status     SMALLINT     NOT NULL DEFAULT 0,              -- 0待支付 1已支付 2已关闭 3已退款
  third_no   VARCHAR(64)  NOT NULL DEFAULT '',             -- 第三方交易号
  pay_at     TIMESTAMP    NULL,
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  updated_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_pay_order_no UNIQUE (order_no),
  CONSTRAINT uk_pay_third_no UNIQUE (third_no)
);
CREATE INDEX idx_pay_user   ON t_pay_order (user_id, created_at);
CREATE INDEX idx_pay_status ON t_pay_order (status, created_at);
COMMENT ON TABLE t_pay_order IS '支付订单';
CREATE TRIGGER trg_pay_order_updated_at BEFORE UPDATE ON t_pay_order
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 12. 增值服务订单（置顶/刷新/加价/加量/快审）
-- ============================================================
DROP TABLE IF EXISTS t_promotion_order;
CREATE TABLE t_promotion_order (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_no     VARCHAR(32)  NOT NULL,
  task_id      BIGINT       NOT NULL,
  publisher_id BIGINT       NOT NULL,
  type         VARCHAR(20)  NOT NULL,                      -- TOP/TOP_SCHEDULED/AUTO_REFRESH/TOP_PACK/REFRESH_PACK/RAISE_PRICE/ADD_QUOTA/FAST_REVIEW
  qty          INTEGER      NOT NULL DEFAULT 1,            -- 购买数量（包类型用）
  unit_price   NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  amount       NUMERIC(12,2) NOT NULL,
  effect_start TIMESTAMP    NULL,
  effect_end   TIMESTAMP    NULL,
  status       SMALLINT     NOT NULL DEFAULT 0,            -- 0待生效 1生效中 2已结束 3已取消
  created_at   TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_promo_order_no UNIQUE (order_no)
);
CREATE INDEX idx_promo_task      ON t_promotion_order (task_id, status);
CREATE INDEX idx_promo_publisher ON t_promotion_order (publisher_id);
COMMENT ON TABLE t_promotion_order IS '增值服务订单';

-- ============================================================
-- 13. 邀请关系
-- ============================================================
DROP TABLE IF EXISTS t_invite;
CREATE TABLE t_invite (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  inviter_id    BIGINT       NOT NULL,
  invitee_id    BIGINT       NOT NULL,
  reward_amount NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  reward_status SMALLINT     NOT NULL DEFAULT 0,           -- 0待发放 1已发放 2已失效
  reward_at     TIMESTAMP    NULL,
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_invitee UNIQUE (invitee_id)
);
CREATE INDEX idx_invite_inviter ON t_invite (inviter_id, created_at);
COMMENT ON TABLE t_invite IS '邀请关系';

-- ============================================================
-- 14. 信誉分变动
-- ============================================================
DROP TABLE IF EXISTS t_credit_log;
CREATE TABLE t_credit_log (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       BIGINT       NOT NULL,
  change_value  INTEGER      NOT NULL,                     -- 正数加，负数减
  balance_after INTEGER      NOT NULL,
  reason        VARCHAR(64)  NOT NULL,                     -- TASK_DONE/TASK_TIMEOUT/REJECTED/INVITE/ADMIN_ADJUST
  biz_id        BIGINT       NOT NULL DEFAULT 0,
  remark        VARCHAR(255) NOT NULL DEFAULT '',
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_credit_user ON t_credit_log (user_id, created_at);
COMMENT ON TABLE t_credit_log IS '信誉分流水';

-- ============================================================
-- 15. 站内信
-- ============================================================
DROP TABLE IF EXISTS t_message;
CREATE TABLE t_message (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    BIGINT       NOT NULL,
  type       SMALLINT     NOT NULL,                        -- 1系统 2任务 3钱包 4审核 5活动
  title      VARCHAR(64)  NOT NULL,
  content    VARCHAR(500) NOT NULL DEFAULT '',
  biz_id     BIGINT       NOT NULL DEFAULT 0,
  is_read    SMALLINT     NOT NULL DEFAULT 0,
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_message_user_read ON t_message (user_id, is_read, created_at);
COMMENT ON TABLE t_message IS '站内信';

-- ============================================================
-- 16. 运营位 / Banner
-- ============================================================
DROP TABLE IF EXISTS t_banner;
CREATE TABLE t_banner (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "position" VARCHAR(32)  NOT NULL,                        -- HOME_TOP/MORE_EARN/MINE_TOP（position 是 PG 关键字，必须加引号）
  title      VARCHAR(64)  NOT NULL DEFAULT '',
  image      VARCHAR(255) NOT NULL,
  link_type  SMALLINT     NOT NULL DEFAULT 0,              -- 0无 1任务 2H5 3会员 4邀请
  link_value VARCHAR(255) NOT NULL DEFAULT '',
  sort       INTEGER      NOT NULL DEFAULT 0,
  status     SMALLINT     NOT NULL DEFAULT 1,
  start_at   TIMESTAMP    NULL,
  end_at     TIMESTAMP    NULL,
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_banner_position ON t_banner ("position", status, sort);
COMMENT ON TABLE t_banner IS '运营位';

-- ============================================================
-- 17. 后台账号
-- ============================================================
DROP TABLE IF EXISTS t_admin_user;
CREATE TABLE t_admin_user (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username      VARCHAR(32)  NOT NULL,
  password_hash VARCHAR(128) NOT NULL,
  salt          VARCHAR(32)  NOT NULL DEFAULT '',
  real_name     VARCHAR(32)  NOT NULL DEFAULT '',
  role          VARCHAR(20)  NOT NULL DEFAULT 'OPERATOR',  -- ADMIN/FINANCE/AUDITOR/OPERATOR
  status        SMALLINT     NOT NULL DEFAULT 1,
  last_login_at TIMESTAMP    NULL,
  created_at    TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  CONSTRAINT uk_username UNIQUE (username)
);
COMMENT ON TABLE t_admin_user IS '后台账号';

-- ============================================================
-- 18. 后台操作审计
-- ============================================================
DROP TABLE IF EXISTS t_admin_log;
CREATE TABLE t_admin_log (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  admin_id   BIGINT       NOT NULL,
  action     VARCHAR(64)  NOT NULL,                        -- TASK_AUDIT/WITHDRAW_AUDIT/REALNAME_AUDIT/...
  target_id  BIGINT       NOT NULL DEFAULT 0,
  detail     TEXT         NULL,                            -- 变更前后 JSON
  ip         VARCHAR(64)  NOT NULL DEFAULT '',
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_admin_log_admin  ON t_admin_log (admin_id, created_at);
CREATE INDEX idx_admin_log_action ON t_admin_log (action, created_at);
COMMENT ON TABLE t_admin_log IS '后台操作日志';

-- ============================================================
-- 19. 设备与风险标记
-- ============================================================
DROP TABLE IF EXISTS t_risk_device;
CREATE TABLE t_risk_device (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  device_id  VARCHAR(64)  NOT NULL,
  user_id    BIGINT       NOT NULL,
  ip         VARCHAR(64)  NOT NULL DEFAULT '',
  risk_level SMALLINT     NOT NULL DEFAULT 0,              -- 0正常 1观察 2限制 3封禁
  risk_tags  VARCHAR(255) NOT NULL DEFAULT '',             -- 多账号/模拟器/改机/黑名单IP
  last_seen  TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP,
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_risk_device_device ON t_risk_device (device_id);
CREATE INDEX idx_risk_device_user   ON t_risk_device (user_id);
CREATE INDEX idx_risk_device_level  ON t_risk_device (risk_level);
COMMENT ON TABLE t_risk_device IS '设备风险';

-- ============================================================
-- 20. 系统配置
-- ============================================================
DROP TABLE IF EXISTS t_sys_config;
CREATE TABLE t_sys_config (
  config_key   VARCHAR(64)   NOT NULL PRIMARY KEY,
  config_value VARCHAR(1000) NOT NULL DEFAULT '',
  remark       VARCHAR(255)  NOT NULL DEFAULT '',
  updated_at   TIMESTAMP     NOT NULL DEFAULT LOCALTIMESTAMP
);
COMMENT ON TABLE t_sys_config IS '系统配置';
CREATE TRIGGER trg_sys_config_updated_at BEFORE UPDATE ON t_sys_config
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============================================================
-- 21. 短信日志（防刷 + 成本核算）
-- ============================================================
DROP TABLE IF EXISTS t_sms_log;
CREATE TABLE t_sms_log (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  phone      VARCHAR(20)  NOT NULL,
  scene      VARCHAR(32)  NOT NULL,                        -- LOGIN/BIND/WITHDRAW_NOTIFY
  code       VARCHAR(8)   NOT NULL DEFAULT '',
  ip         VARCHAR(64)  NOT NULL DEFAULT '',
  status     SMALLINT     NOT NULL DEFAULT 0,              -- 0发送中 1成功 2失败
  biz_id     VARCHAR(64)  NOT NULL DEFAULT '',
  created_at TIMESTAMP    NOT NULL DEFAULT LOCALTIMESTAMP
);
CREATE INDEX idx_sms_phone_time ON t_sms_log (phone, created_at);
CREATE INDEX idx_sms_ip_time    ON t_sms_log (ip, created_at);
COMMENT ON TABLE t_sms_log IS '短信发送日志';

